'use strict';
const $ = (s, root = document) => root.querySelector(s);
const app = $('#app');
const modal = $('#modal');
const state = {csrf:'',issues:[],runs:[],integration_tests:[],availability:[],filters:[],activity:[],meta:{},view:'overview',category:'all',compare:null,page:1,pageSize:50,filter:{q:'',status:'all',risk:'all',scope:'all',verified:'all'}};
const navItems = [ ['overview','Visão geral','grid'], ['issues','Issues & pull requests','issue'], ['runs','Execuções & sandbox','terminal'], ['integration','Matriz de integração','layers'], ['compare','Comparar commits','branch'], ['availability','Integração instalável','package'], ['activity','Registro de atividade','clock'] ];
const paths = {grid:'<rect x="3" y="3" width="7" height="7" rx="1.3"/><rect x="14" y="3" width="7" height="7" rx="1.3"/><rect x="3" y="14" width="7" height="7" rx="1.3"/><rect x="14" y="14" width="7" height="7" rx="1.3"/>',issue:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7v6m0 3h.01"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3m6 0h4"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',branch:'<circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="5" r="2"/><path d="M6 7v10m0-3c0-5 12-1 12-7"/>',package:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 10v9M3 8l9 5 9-5M7 5.8l9 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',external:'<path d="M14 3h7v7m0-7-11 11M10 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8L3 5Z"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-8h10v8"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 6.1A8 8 0 0 1 20 12M4 12a8 8 0 0 0 13.9 5.9"/>',github:'<path d="M9 19c-4 1-4-2-6-2m12 5v-4a3.5 3.5 0 0 0-1-2.7c3.4-.4 7-1.7 7-7.3a5.8 5.8 0 0 0-1.6-4c.2-1 .1-2.2-.4-3-1.5 0-3 1-4 1.7a14 14 0 0 0-7 0C7 .9 5.5 0 4 0c-.5.8-.6 2-.4 3A5.8 5.8 0 0 0 2 7c0 5.6 3.6 6.9 7 7.3A3.5 3.5 0 0 0 8 17v5" transform="translate(1 1) scale(.9)"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',flask:'<path d="M9 3h6m-5 0v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 4H4v16h5m5-13 5 5-5 5m-7-5h12"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7a2 2 0 0 0-5-5L3 16v5Z"/>',note:'<path d="M5 3h10l5 5v13H5V3Zm10 0v6h5M8 13h9m-9 4h6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-5-5l4-4a4 4 0 0 1 6 0m2 8a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-2 2" transform="translate(1 0) scale(.9)"/>',commit:'<path d="M3 12h5m8 0h5"/><circle cx="12" cy="12" r="4"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',warning:'<path d="M12 3 2 21h20L12 3Zm0 6v5m0 3h.01"/>',os:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>'};
const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}">${paths[name]||paths.info}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=v=>Array.isArray(v)?v:(v?String(v).split('\n').filter(Boolean):[]);
const shorten=(v,n=9)=>String(v||'').slice(0,n)||'não informado';
const date=(v,full=false)=>{if(!v)return 'sem registro';const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(String(v))?`${v}T12:00:00Z`:v);return Number.isNaN(d.getTime())?'sem registro':new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',...(full?{year:'numeric',hour:'2-digit',minute:'2-digit'}:{})}).format(d)};
const safeUrl=v=>{try{const u=new URL(v);return u.protocol==='https:'?u.href:'#'}catch{return '#'}};
const link=(url,label,cls='')=>safeUrl(url)==='#'?`<span class="${cls}">${esc(label)}</span>`:`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer" class="${cls}">${esc(label)} ${icon('external')}</a>`;
const scopeLabels={isolated:'Isolado',gui:'GUI',parser:'Parser',full:'Suite completa',e2e:'Ponta a ponta'};
const riskLabels={critical:'Crítico',high:'Alto',medium:'Médio',low:'Baixo',unknown:'A avaliar'};
const statusLabels={open:'Aberta',closed:'Fechada',merged:'Integrado',pending:'Pendente',passed:'Aprovado',failed:'Falhou',blocked:'Bloqueado',unconfirmed:'Não confirmado',confirmed:'Confirmado',unavailable:'Indisponível',in_progress:'Em andamento',fixed:'Corrigido',verified:'Verificado',needs_validation:'Validar localmente',unknown:'A verificar',documented:'Documentado',commit_identified:'Commit identificado',merged_upstream_pending_local_validation:'Integrado · validar localmente',not_started:'Não iniciado'};
const statusTone={open:'yellow',closed:'neutral',merged:'blue',pending:'yellow',passed:'green',failed:'red',blocked:'red',unconfirmed:'yellow',confirmed:'green',unavailable:'neutral',in_progress:'blue',fixed:'blue',verified:'green',needs_validation:'yellow',documented:'blue'};
const pill=(label,tone='neutral',ic='')=>`<span class="pill ${tone}">${ic?icon(ic):''}${esc(label)}</span>`;
const badge=status=>pill(statusLabels[status]||status||'A verificar',statusTone[status]||'neutral');
const riskBadge=risk=>pill(riskLabels[risk]||risk||'A avaliar',({critical:'red',high:'yellow',medium:'blue',low:'neutral'})[risk]||'neutral');
const priority=p=>`<span class="priority ${esc(String(p||'P2').toLowerCase())}">${icon('layers')}${esc(p||'P2')}</span>`;
const issueId=x=>String(x.id??x.number);
const getIssue=id=>state.issues.find(x=>issueId(x)===String(id));
const runsFor=id=>state.runs.filter(r=>String(r.issue_id)===String(id));
const issueSorted=()=>[...state.issues].sort((a,b)=>{const order=[12189,12187,12185,12186];let ai=order.indexOf(Number(a.id)),bi=order.indexOf(Number(b.id));return (ai<0?99:ai)-(bi<0?99:bi)||String(a.priority||'P2').localeCompare(String(b.priority||'P2'))||Number(b.id)-Number(a.id)});
function verifiedE2e(r){return r.scope==='e2e'&&r.mode==='live'&&r.status==='passed'&&r.verified===true}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5500)}
async function api(action,data=null){const response=await fetch(`api.php?action=${encodeURIComponent(action)}`,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify({csrf:state.csrf,...data}):undefined});let result;try{result=await response.json()}catch{throw new Error('O servidor retornou uma resposta inválida. Confira a configuração PHP.')}if(!response.ok){const error=new Error(result.error||result.message||`Falha HTTP ${response.status}`);error.status=response.status;throw error}return result}
async function load(){try{const data=await api('bootstrap');for(const key of ['issues','runs','integration_tests','availability','filters','activity'])state[key]=Array.isArray(data[key])?data[key]:[];state.meta=data.meta||{};state.csrf=data.csrf||state.csrf;render()}catch(e){if(e.status===401||e.status===503){await renderLogin(e.message)}else{app.innerHTML=`<div class="login-page"><div class="login-card"><div class="brand-mark">m<span>_</span></div><h1 class="section-gap">Não foi possível carregar</h1><p>${esc(e.message)}</p><button class="button primary" data-action="reload">Tentar novamente</button></div></div>`}}}
async function mutate(action,data,message='Registro salvo.'){const result=await api(action,data);await load();if(message)toast(message);return result}
function readLocation(){const params=new URLSearchParams(location.search);if(navItems.some(n=>n[0]===params.get('view')))state.view=params.get('view');for(const key of Object.keys(state.filter))if(params.has(key))state.filter[key]=params.get(key)}
function updateLocation(){const params=new URLSearchParams();params.set('view',state.view);for(const [key,value] of Object.entries(state.filter))if(value&&value!=='all')params.set(key,value);history.replaceState(null,'',`${location.pathname}?${params}`)}
function navigate(view){if(view==='issues'&&!['all','open','closed','merged'].includes(state.filter.status))state.filter.status='all';if(view==='runs'&&!['all','passed','failed','pending','blocked'].includes(state.filter.status))state.filter.status='all';state.view=view;state.compare=null;state.page=1;updateLocation();render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true})}
function render(){const item=navItems.find(n=>n[0]===state.view)||navItems[0];const required=state.integration_tests.filter(t=>t.status!=='passed').length;app.innerHTML=`<aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">m<span>_</span></div><div><div class="brand-name">Mudlet</div><div class="brand-sub">Control Room</div></div></div><div class="workspace-label eyebrow">Workspace</div><nav class="nav" aria-label="Navegação principal">${navItems.map(([id,label,ic])=>`<button class="nav-btn ${state.view===id?'active':''}" data-view="${id}" ${state.view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='integration'&&required?`<span class="nav-count">${required}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="protocol-card"><div class="protocol-label"><span class="dot"></span> Mudlet ↔ ChatGPT</div><p>Evidências por commit.<br>Confiança construída a cada teste.</p></div><div class="sidebar-foot"><div class="avatar">CR</div><div><span>Ambiente de validação</span><small>${state.meta.dev_local?'Desenvolvimento local':'Armazenamento persistente'}</small></div><button class="icon-btn" data-action="logout" title="Encerrar sessão" aria-label="Encerrar sessão">${icon('logout')}</button></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegação">${icon('menu')}</button><span class="workspace-crumb">Workspace</span><span class="slash workspace-crumb">/</span><strong>${esc(item[1])}</strong></div><div class="topbar-right"><span class="live-label"><span class="dot"></span> Registro de evidências</span><span class="topbar-divider"></span><a class="github-link" href="https://github.com/Mudlet/Mudlet" target="_blank" rel="noopener noreferrer">${icon('github')}<span>Mudlet / Mudlet</span></a><button class="icon-btn" data-action="reload" title="Atualizar dados locais" aria-label="Atualizar dados locais">${icon('refresh')}</button></div></header><main id="main" tabindex="-1">${renderView()}<footer class="footer"><span><span class="dot"></span> Mudlet Control Room <span class="mono">/</span> Evidências antes de conclusões</span><span>Dados locais · ${esc(date(state.meta.updated_at||state.meta.generated_at||new Date().toISOString(),true))}</span></footer></main></div>`}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`}
function empty(title,description,ic='flask',action=''){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`}
function renderView(){switch(state.view){case 'issues':return renderIssues();case 'runs':return renderRuns();case 'integration':return renderIntegration();case 'compare':return renderCompare();case 'availability':return renderAvailability();case 'activity':return renderActivity();default:return renderOverview()}}
function renderOverview(){const e2e=state.runs.filter(verifiedE2e).length;const verified=state.runs.filter(r=>r.verified).length;const pending=state.integration_tests.filter(t=>t.status!=='passed').length;const priorityIssues=issueSorted().filter(i=>[12189,12187,12185,12186].includes(Number(i.id)));const snapshot=state.meta.github_synced_at||state.meta.source_checked_at||state.meta.github_sync?.checked_at||state.meta.researched_at||state.meta.generated_at;return `${heading('Engineering workspace','Controle de integração','Desenvolvimento do Mudlet. Evidências, testes e próximos passos em um só lugar.',`<a class="button ghost" href="api.php?action=export">${icon('download')}Exportar dados</a><button class="button primary" data-action="new-run">${icon('plus')}Registrar execução</button>`)}<div class="snapshot"><div class="snapshot-main">${icon('info')}<span>GitHub e validação local são estados distintos. Uma issue fechada ainda pode precisar de testes de ponta a ponta.</span></div><a href="https://github.com/Mudlet/Mudlet/issues" target="_blank" rel="noopener noreferrer">Consultar fonte ${icon('external')}</a></div><div class="metrics">${metric('Issues & pull requests',state.issues.length,'Sincronização pelo CLI · todas as páginas','issue')}${metric('Execuções registradas',state.runs.length,`${verified} verificadas por um revisor`,'terminal')}${metric('E2E com evidência',e2e,'Histórico · live aprovado e revisado','shield',true)}${metric('Integrações pendentes',pending,`${state.integration_tests.length} cenários na matriz de validação`,'layers',true)}</div><div class="dashboard-grid"><div class="dashboard-left"><section class="panel"><div class="panel-header"><div><h2>Fila de prioridade <span class="counter">${priorityIssues.length}</span></h2><p class="panel-subtitle">Ordem recomendada para a próxima validação</p></div><button class="text-btn" data-view="issues">Todas as issues ${icon('arrow')}</button></div><div class="priority-strip"><strong>Sequência recomendada</strong><span>#12189</span><span class="arrow">→</span><span>#12187</span><span class="arrow">→</span><span>#12185</span><span class="arrow">→</span><span>#12186</span></div>${priorityIssues.length?`<div class="table-scroll"><table class="priority-table"><thead><tr><th>Ordem</th><th>Issue / contexto</th><th>Prioridade</th><th class="github-col">GitHub</th><th class="validation-col">Validação local</th><th></th></tr></thead><tbody>${priorityIssues.map((i,n)=>issueRow(i,n+1,true)).join('')}</tbody></table></div>`:empty('Fila inicial não carregada','Importe os dados do GitHub pelo CLI ou cadastre as issues prioritárias.','issue')}<div class="panel-footer"><span>Estado público consultado ${esc(date(snapshot))}</span><span>Fechada ≠ E2E comprovado</span></div></section><section class="panel"><div class="panel-header"><div><h2>Últimas execuções</h2><p class="panel-subtitle">Resultados com ambiente e commit rastreáveis</p></div><button class="text-btn" data-view="runs">Abrir sandbox ${icon('arrow')}</button></div>${state.runs.length?`<div class="table-scroll"><table class="table-compact"><thead><tr><th>Issue / commit</th><th>Escopo</th><th>Modo</th><th>Resultado</th><th></th></tr></thead><tbody>${[...state.runs].reverse().slice(0,4).map(run=>`<tr><td><button class="issue-title" data-action="run-detail" data-id="${esc(run.id)}">#${esc(run.issue_id)} <span class="mono muted">${esc(shorten(run.commit_sha))}</span></button><div class="cell-sub">${esc(run.os||'SO não informado')}</div></td><td>${pill(scopeLabels[run.scope]||run.scope)}</td><td>${pill(run.mode||'mock',run.mode==='live'?'blue':'neutral')}</td><td>${badge(run.status)}</td><td>${run.verified?`<span class="verified" title="Revisado por ${esc(run.reviewer)}">${icon('checkcircle')}</span>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sua primeira execução começa aqui','Registre os resultados do runner ou de um teste manual. Nenhuma aprovação é presumida.','terminal',`<button class="button small" data-action="new-run">${icon('plus')}Registrar resultado</button>`)}<div class="scope-legend">${[['isolated','flask','Método ou unidade'],['gui','os','Interface em execução'],['parser','code','Entradas reais do parser'],['full','layers','Suite completa do Mudlet']].map(([s,ic,desc])=>`<div class="scope-item"><span>${icon(ic)}${scopeLabels[s]}</span><p>${desc}</p></div>`).join('')}</div></section></div><aside class="dashboard-right"><section class="panel"><div class="panel-header"><div><h2>Próximas integrações</h2><p class="panel-subtitle">${pending} validações ainda necessárias</p></div><span class="mini-icon">${icon('layers')}</span></div><div class="next-list">${state.integration_tests.slice(0,4).map((t,n)=>`<div class="next-item"><span class="step-index">0${n+1}</span><div><h3>${esc(t.title)}</h3><p>${esc(t.summary||t.description||t.notes||'Execute no Mudlet e anexe a evidência do cenário.')}</p>${badge(t.status||'pending')}</div></div>`).join('')||`<div class="next-item"><p class="small muted">Matriz ainda não carregada.</p></div>`}</div><div class="panel-footer"><button class="text-btn" data-view="integration">Ver matriz de integração ${icon('arrow')}</button></div></section><section class="panel"><div class="panel-header"><h2>Em acompanhamento</h2>${icon('branch')}</div><div class="timeline">${[8576,12128].map(n=>{const i=getIssue(n);return `<div class="timeline-item"><div class="timeline-icon">${icon('branch')}</div><div><p><button class="issue-title" data-action="issue-detail" data-id="${n}">PR #${n}</button>${esc(i?.title||'Consultar pull request')}</p><small>${esc(statusLabels[i?.github_state||i?.status]||i?.github_state||i?.status||'Estado a verificar')} · ${runsFor(n).length} execuções locais</small></div></div>`}).join('')}<div class="timeline-item"><div class="timeline-icon">${icon('shield')}</div><div><p>Sanitizer compartilhado</p><small>${esc(state.meta.sanitizer?.status==='merged_upstream_pending_local_validation'?'Integrado no PR #12128 · reteste local pendente':'Acompanhar pedido e implementação.')}</small></div></div></div></section><div class="release-callout"><div class="eyebrow">Radar de disponibilidade</div><h3>Suporte MCP ≠ integração pronta</h3><p>Separe suporte nativo, transporte compatível com ChatGPT e pacotes instaláveis com fonte primária.</p><button class="text-btn" data-view="availability">Consultar evidências ${icon('arrow')}</button></div></aside></div>`}
function metric(label,value,foot,ic,accent=false){return `<div class="metric"><div class="metric-top"><span>${esc(label)}</span>${icon(ic)}</div><div class="metric-value">${esc(value)}${label.startsWith('E2E')?'<small>live</small>':''}</div><div class="metric-foot ${accent?'accent':''}"><span class="dot"></span>${esc(foot)}</div></div>`}
function localValidation(i){
  const runs=runsFor(i.id);
  if(!runs.length)return pill('A validar','yellow');
  const dated=runs.map((run,index)=>({run,index,time:Number.isNaN(Date.parse(run.created_at))?0:Date.parse(run.created_at)}));
  dated.sort((a,b)=>b.time-a.time||b.index-a.index);
  const latestCommit=dated[0].run.commit_sha||dated[0].run.commit||'';
  const current=runs.filter(r=>(r.commit_sha||r.commit||'')===latestCommit);
  if(current.some(r=>r.status==='failed'))return pill('Falha neste commit','red');
  if(current.some(verifiedE2e))return pill('E2E neste commit','green','checkcircle');
  return pill('Evidência parcial','blue');
}
function issueRow(i,rank=0,compact=false){return `<tr>${compact?`<td><span class="rank">${rank}</span></td>`:''}<td><div class="issue-cell">${icon(i.kind==='pr'?'branch':'issue')}<div><div class="issue-id">${i.kind==='pr'?'PR':'ISSUE'} #${esc(i.id)}</div><button class="issue-title" data-action="issue-detail" data-id="${esc(i.id)}">${esc(i.title||'Sem título')}</button>${!compact?`<div class="cell-sub">${esc(i.summary||'Fonte e evidências no detalhe').slice(0,110)}</div>`:''}</div></div></td><td>${priority(i.priority)}</td><td class="github-col">${badge(i.github_state||i.status)}</td>${!compact?`<td>${riskBadge(i.risk)}</td>`:''}<td class="validation-col">${localValidation(i)}</td><td><button class="icon-btn" data-action="issue-detail" data-id="${esc(i.id)}" aria-label="Abrir issue ${esc(i.id)}">${icon('chevron')}</button></td></tr>`}
function filterIssues(){const f=state.filter,q=f.q.toLowerCase();return issueSorted().filter(i=>(!q||`${i.id} ${i.title} ${i.summary||''}`.toLowerCase().includes(q))&&(f.status==='all'||(i.github_state||i.status)===f.status)&&(f.risk==='all'||i.risk===f.risk))}
function filterRuns(){const f=state.filter,q=f.q.toLowerCase();return [...state.runs].reverse().filter(r=>(!q||`${r.issue_id} ${r.commit_sha} ${r.os} ${r.id}`.toLowerCase().includes(q))&&(f.status==='all'||r.status===f.status)&&(f.risk==='all'||r.risk===f.risk)&&(f.scope==='all'||r.scope===f.scope)&&(f.verified==='all'||String(Boolean(r.verified))===f.verified))}
function options(items,current){if(current!==undefined&&current!==null&&String(current)!==''&&!items.some(([value])=>String(value)===String(current)))items=[[current,statusLabels[current]||riskLabels[current]||String(current)],...items];return items.map(([value,label])=>`<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}
function filterbar(runs=false){return `<div class="filterbar"><label class="searchbox">${icon('search')}<input id="search" type="search" value="${esc(state.filter.q)}" placeholder="${runs?'Buscar issue, commit, sistema…':'Buscar por número, título ou contexto…'}" aria-label="Buscar registros"></label><select data-filter="status" aria-label="Filtrar estado">${options(runs?[['all','Resultado: todos'],['passed','Aprovados'],['failed','Falhas'],['pending','Pendentes'],['blocked','Bloqueados']]:[['all','GitHub: todos'],['open','Abertas'],['closed','Fechadas'],['merged','Integrados']],state.filter.status)}</select><select data-filter="risk" aria-label="Filtrar risco">${options([['all','Risco: todos'],...Object.entries(riskLabels)],state.filter.risk)}</select>${runs?`<select data-filter="scope" aria-label="Filtrar escopo">${options([['all','Escopo: todos'],...Object.entries(scopeLabels)],state.filter.scope)}</select><select data-filter="verified" aria-label="Filtrar revisão">${options([['all','Revisão: todas'],['true','Verificados'],['false','Não verificados']],state.filter.verified)}</select>`:''}<button class="button ghost small" data-action="save-filter" title="Salvar filtros atuais">${icon('save')}Salvar filtro</button></div><div class="saved-filters"><span>Filtros salvos</span>${state.filters.length?state.filters.map(f=>`<span class="filter-chip"><button data-action="apply-filter" data-id="${esc(f.id)}">${esc(f.name)}</button><button data-action="remove-filter" data-id="${esc(f.id)}" aria-label="Remover filtro ${esc(f.name)}">×</button></span>`).join(''):'<span>· Salve uma seleção para reutilizar depois.</span>'}<button class="text-btn" data-action="clear-filters">Limpar</button></div>`}
function renderIssues(){const rows=filterIssues();return `${heading('Rastreabilidade por issue','Issues & pull requests','Relacione código, discussões, builds e resultados sem perder o contexto.',`<a class="button ghost" href="api.php?action=export">${icon('download')}Exportar</a><button class="button primary" data-action="new-issue">${icon('plus')}Adicionar issue</button>`)}<div class="notice">${icon('branch')}<div>Prioridade recomendada: <strong>#12189 → #12187 → #12185 → #12186</strong>. A sincronização CLI importa todas as issues e PRs, sem limitar esta lista aos itens iniciais.</div></div>${githubCoverage()}<section class="panel">${filterbar()}<div id="filtered-content">${issuesTable(rows)}</div></section>`}
function githubCoverage(){const sync=state.meta.github_sync;if(!sync)return '';return `<div class="snapshot"><div class="snapshot-main">${icon(sync.complete?'checkcircle':'info')}<span>GitHub: ${sync.complete?'inventário completo':'inventário parcial'} · ${esc(sync.imported_count??state.issues.length)} issues/PRs · ${esc(date(sync.checked_at,true))}. Detalhes de comentários, revisões e builds: ${esc(list(sync.detail_ids).map(n=>'#'+n).join(', ')||'não importados')}.</span></div></div>`}
function pagination(total){const pages=Math.max(1,Math.ceil(total/state.pageSize));state.page=Math.min(state.page,pages);return `<div class="pagination"><span>${total?((state.page-1)*state.pageSize+1):0}–${Math.min(state.page*state.pageSize,total)} de ${total}</span><div class="actions"><button class="button small ghost" data-action="page-prev" ${state.page<=1?'disabled':''}>Anterior</button><span>Página ${state.page} de ${pages}</span><button class="button small ghost" data-action="page-next" ${state.page>=pages?'disabled':''}>Próxima</button></div></div>`}
function issuesTable(rows){const footer=pagination(rows.length);const page=rows.slice((state.page-1)*state.pageSize,state.page*state.pageSize);return rows.length?`<div class="table-scroll"><table><thead><tr><th>Issue / pull request</th><th>Prioridade</th><th>GitHub</th><th>Risco</th><th>Validação local</th><th></th></tr></thead><tbody>${page.map(i=>issueRow(i)).join('')}</tbody></table></div>${footer}`:empty('Nenhuma issue nesta seleção','Ajuste os filtros ou adicione uma issue para começar.','issue')}
function renderRuns(){const rows=filterRuns();return `${heading('Evidências de execução','Execuções & sandbox','Cada resultado pertence a um commit, um ambiente e um escopo de teste.',`<a class="button ghost" href="api.php?action=export">${icon('download')}Exportar</a><button class="button primary" data-action="new-run">${icon('plus')}Registrar execução</button>`)}<div class="notice">${icon('terminal')}<div>Use o runner CLI para testar <strong>mock ou live</strong> em um endpoint loopback. O formulário registra evidências; a interface não executa comandos Lua. Testes isolados, GUI, parser e suite completa têm coberturas diferentes.</div></div><section class="panel">${filterbar(true)}<div id="filtered-content">${runsTable(rows)}</div></section>`}
function runsTable(rows){const footer=pagination(rows.length);const page=rows.slice((state.page-1)*state.pageSize,state.page*state.pageSize);return rows.length?`<div class="table-scroll"><table class="table-compact"><thead><tr><th>Issue / commit</th><th>Ambiente</th><th>Escopo</th><th>Modo</th><th>Asserções</th><th>Resultado</th><th>Revisão</th><th></th></tr></thead><tbody>${page.map(r=>`<tr><td><button class="issue-title" data-action="run-detail" data-id="${esc(r.id)}">#${esc(r.issue_id)} <span class="mono">${esc(shorten(r.commit_sha))}</span></button><div class="cell-sub">${esc(date(r.created_at,true))}</div></td><td>${esc(r.os||'Não informado')}<div class="cell-sub mono">MCP ${esc(r.protocol_version||'?')}</div></td><td>${pill(scopeLabels[r.scope]||r.scope)}</td><td>${pill(r.mode,r.mode==='live'?'blue':'neutral')}</td><td class="nowrap"><span class="text-accent">${list(r.assertions_passed).length} ✓</span> <span class="muted">/</span> <span class="${list(r.assertions_failed).length?'text-danger':'muted'}">${list(r.assertions_failed).length} ✕</span></td><td>${badge(r.status)}</td><td>${r.verified?`<span class="verified">${icon('checkcircle')}${esc(r.reviewer||'Verificado')}</span>`:`<button class="button ghost small" data-action="verify-run" data-id="${esc(r.id)}">Verificar</button>`}</td><td><button class="icon-btn" data-action="run-detail" data-id="${esc(r.id)}" aria-label="Detalhar execução">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${footer}`:empty('Nenhum resultado nesta seleção',state.runs.length?'Ajuste os filtros para encontrar as execuções.':'Registre um teste manual ou importe a saída do runner CLI.','terminal',`<button class="button small" data-action="new-run">${icon('plus')}Registrar execução</button>`)}
function renderIntegration(){const pending=state.integration_tests.filter(t=>t.status!=='passed').length;return `${heading('Cobertura real','Matriz de integração',`${pending} cenários ainda pendentes. Cada aprovação deve ter execução e evidência rastreáveis.`,`<button class="button primary" data-action="new-run">${icon('plus')}Registrar execução</button>`)}<div class="notice">${icon('shield')}<div><strong>Isolado, GUI, parser, suite e E2E são escopos diferentes.</strong> Um teste mock ou de método isolado não comprova a integração Mudlet–ChatGPT. E2E comprovado exige execução live aprovada e revisada.</div></div>${state.meta.integration_plan_note?`<p class="small muted integration-plan-note">${esc(state.meta.integration_plan_note)}</p>`:''}<div class="two-col">${state.integration_tests.map((t,n)=>`<section class="integration-card"><div class="card-top"><span class="eyebrow">${t.origin==='local_proposed_plan'?'Plano local':'Integração'} 0${n+1}</span>${badge(t.status||'pending')}</div><h2>${esc(t.title)}</h2><p>${esc(t.description||t.summary||t.notes||'Validação a executar no ambiente completo.')}</p>${list(t.assertions).length?`<div class="detail-section"><h3>Asserções planejadas</h3><ul>${list(t.assertions).map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`:''}${t.acceptance?`<div class="detail-section"><h3>Critério de aprovação</h3><p>${esc(Array.isArray(t.acceptance)?t.acceptance.join(' · '):t.acceptance)}</p></div>`:''}${t.notes?`<p><span class="small text-accent">Evidência / observação:</span> ${esc(t.notes)}</p>`:''}<div class="card-footer"><span>${esc(scopeLabels[t.scope]||t.scope||'GUI / parser / E2E')}</span><button class="button small" data-action="edit-integration" data-id="${esc(t.id)}">${icon('edit')}Atualizar evidência</button></div></section>`).join('')||empty('Matriz não carregada','Revise o arquivo de dados inicial.','layers')}</div><div class="section-gap two-col"><section class="panel"><div class="panel-header"><h2>Critérios de evidência</h2>${icon('checkcircle')}</div><div class="panel-body"><div class="detail-description">Registre commit completo, hash do método-fonte, sistema operacional, protocolo MCP, ferramentas e entradas de reprodução. Anexe o resultado do sandbox e as asserções aprovadas ou falhadas. Marque como verificado somente após a revisão.</div></div></section><section class="panel"><div class="panel-header"><h2>Sanitizer compartilhado</h2>${icon('code')}</div><div class="panel-body"><div class="detail-description">${state.meta.sanitizer?.status==='merged_upstream_pending_local_validation'?'O sanitizer compartilhado foi integrado no PR #12128. A validação local do portal e dos caminhos OSC 8/MXP continua pendente.':'Acompanhe a proposta, os call sites e testes relacionados por issue. Registre a implementação como concluída somente com código e evidência.'}</div>${state.meta.sanitizer?.request_url?`<div class="source-row">${link(state.meta.sanitizer.request_url,'Pedido original')}${state.meta.sanitizer.latest_approval_url?link(state.meta.sanitizer.latest_approval_url,'Revisão final'):''}</div>`:''}<button class="text-btn section-gap" data-action="sanitizer">Ver registros relacionados ${icon('arrow')}</button></div></section></div>`}
function renderCompare(){return `${heading('Regressões & evolução','Comparar commits','Compare os resultados registrados para dois commits e identifique o que mudou.')}<section class="panel"><div class="panel-header"><div><h2>Selecione dois commits</h2><p class="panel-subtitle">Comparação de evidências locais; diferenças de código são consultadas no GitHub.</p></div>${icon('branch')}</div><div class="panel-body"><form id="compare-form" class="compare-form"><div class="form-field"><label for="base">Commit base</label><input id="base" name="base" required pattern="(?:[a-fA-F0-9]{40}|[a-fA-F0-9]{64})" placeholder="SHA do commit anterior" value="${esc(state.compare?.base||'')}" autocomplete="off"><small>Use o SHA completo para uma comparação inequívoca.</small></div><div class="between">${icon('arrow')}</div><div class="form-field"><label for="head">Commit de comparação</label><input id="head" name="head" required pattern="(?:[a-fA-F0-9]{40}|[a-fA-F0-9]{64})" placeholder="SHA do commit atual" value="${esc(state.compare?.head||'')}" autocomplete="off"><small>Compare o mesmo ambiente e escopo de teste.</small></div><button class="button primary" type="submit">${icon('branch')}Comparar</button></form></div></section><div id="compare-result">${state.compare?compareResult(state.compare):`<div class="section-gap panel">${empty('Encontre o impacto de cada commit','A comparação mostra resultados, falhas e mudanças por issue. Registre execuções dos dois commits antes de concluir que uma correção foi validada.','branch')}</div>`}</div>`}
function compareResult(c){const s=c.summary||{};return `<div class="compare-result"><div class="metrics">${metric('Execuções na base',s.base_runs??0,'Registros encontrados','commit')}${metric('Execuções no destino',s.head_runs??0,'Registros encontrados','commit')}${metric('Variação de aprovados',`${Number(s.passed_delta||0)>0?'+':''}${s.passed_delta??0}`,'Não implica equivalência de ambiente','checkcircle')}${metric('Variação de falhas',`${Number(s.failed_delta||0)>0?'+':''}${s.failed_delta??0}`,'Revisar escopo e ambiente','warning')}</div><section class="panel"><div class="panel-header"><h2>Diferenças por issue</h2>${link(`https://github.com/Mudlet/Mudlet/compare/${encodeURIComponent(c.base)}...${encodeURIComponent(c.head)}`,'Diff no GitHub','small')}</div>${c.rows?.length?`<div class="table-scroll"><table><thead><tr><th>Issue</th><th>Base</th><th>Destino</th><th>Leitura</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td><button class="issue-title" data-action="issue-detail" data-id="${esc(r.issue_id)}">#${esc(r.issue_id)}</button></td><td>${esc(compareCounts(r.base))}</td><td>${esc(compareCounts(r.head))}</td><td>${esc(r.change)}</td></tr>`).join('')}</tbody></table></div>`:empty('Sem pares de resultados','Não há evidência suficiente para afirmar regressão ou correção entre estes commits.','branch')}<div class="panel-body">${list(c.changes).map(t=>`<p class="compare-change">${esc(t)}</p>`).join('')}<p class="small muted">Ambientes, ferramentas e escopos diferentes exigem nova execução equivalente. Ausência de falha não é evidência de cobertura.</p></div></section></div>`}
function compareCounts(v){if(!v)return 'Sem execuções';if(typeof v==='string')return v;return Object.entries(v).map(([k,x])=>`${k}: ${typeof x==='object'?JSON.stringify(x):x}`).join(' · ')}
const categoryLabels={native:'Suporte nativo',plugin:'Plugins',connector:'Conectores',package:'Pacotes',repository:'Repositórios independentes'};
function renderAvailability(){const entries=state.availability.filter(e=>state.category==='all'||e.category===state.category);return `${heading('Radar de disponibilidade','Integração instalável','Fontes primárias, versões e artefatos. Cada categoria tem seu próprio estado.',`<button class="button primary" data-action="new-availability">${icon('plus')}Registrar evidência</button>`)}<div class="notice">${icon('info')}<div><strong>Uma menção não confirma uma integração instalável.</strong> Rumores, conteúdo reciclado e MCP nativo não comprovam um conector Mudlet–ChatGPT. Confirme transporte, pacote utilizável, versão, origem e data da checagem.</div></div><div class="availability-tabs" role="group" aria-label="Categoria de disponibilidade">${[['all','Todas as categorias'],...Object.entries(categoryLabels)].map(([value,label])=>`<button class="availability-tab ${state.category===value?'active':''}" data-category="${value}" aria-pressed="${state.category===value}">${esc(label)}</button>`).join('')}</div><section class="panel">${entries.length?entries.map(e=>`<article class="availability-entry"><div class="availability-icon">${icon(e.category==='native'?'code':e.category==='repository'?'github':'package')}</div><div class="availability-content"><div class="eyebrow small">${esc(categoryLabels[e.category]||e.category)}</div><h3>${esc(e.name||e.title)}</h3><p>${esc(e.notes||e.summary||'Evidência ainda não detalhada.')}</p><div class="source-row">${e.source_url?link(e.source_url,'Fonte primária'): '<span>Sem fonte primária anexada</span>'}<span>Checado em ${esc(date(e.checked_at,true))}</span>${e.version?`<span class="mono">${esc(e.version)}</span>`:''}</div></div><div class="entry-right">${badge(e.status||'unconfirmed')}<button class="text-btn" data-action="edit-availability" data-id="${esc(e.id)}">Editar registro ${icon('edit')}</button></div></article>`).join(''):empty('Nenhuma evidência nesta categoria','Registre uma fonte primária e mantenha o estado não confirmado enquanto faltar um artefato verificável.','package')}</section><div class="section-gap two-col"><section class="panel"><div class="panel-header"><h2>Confirmado em qual nível?</h2>${icon('shield')}</div><div class="panel-body"><p class="detail-description">Suporte MCP nativo confirma a capacidade do Mudlet. Um plugin ou pacote confirma um artefato distribuído. A conexão com ChatGPT precisa também de transporte acessível, configuração compatível e teste real. Registre esses fatos separadamente.</p></div></section><section class="panel"><div class="panel-header"><h2>Próxima checagem</h2>${icon('search')}</div><div class="panel-body"><p class="detail-description">Use releases oficiais, documentação do projeto e repositórios do autor. Confirme instruções de instalação, versão e teste reproduzível. Sem evidência suficiente, mantenha “Não confirmado” e registre o que falta.</p></div></section></div>`}
function renderActivity(){const rows=[...state.activity].reverse();return `${heading('Histórico auditável','Registro de atividade','Alterações, revisões e importações feitas neste Control Room.',`<a class="button" href="api.php?action=export">${icon('download')}Exportar histórico</a>`)}<section class="panel">${rows.length?`<div class="timeline activity-full">${rows.map(a=>`<div class="timeline-item"><div class="timeline-icon">${icon(String(a.action||a.type).includes('verif')?'shield':String(a.action||a.type).includes('run')?'terminal':'clock')}</div><div><p>${esc(a.message||a.description||a.action||a.type||'Registro atualizado')}</p><small>${esc(date(a.created_at||a.at||a.timestamp,true))}${a.actor?` · ${esc(a.actor)}`:''}${a.issue_id?` · #${esc(a.issue_id)}`:''}</small>${a.details?`<div class="cell-sub">${esc(typeof a.details==='object'?JSON.stringify(a.details):a.details)}</div>`:''}</div></div>`).join('')}</div>`:empty('O histórico começa nas suas ações','Novos registros e verificações aparecerão aqui.','clock')}</section>`}
function showModal(title,subtitle,body,footer=''){const old=$('#modal-content');old.innerHTML=`<div class="modal-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${icon('close')}</button></div>${body}${footer}`;if(!modal.open)modal.showModal()}
const closeModal=()=>modal.close();
function field(name,label,value='',opts={}){const required=opts.required?' required':'';const cls=opts.full?' full':'';const id=`field-${name}`;const control=opts.options?`<select id="${id}" name="${name}"${required}>${options(opts.options,value)}</select>`:opts.textarea?`<textarea id="${id}" name="${name}" rows="${opts.rows||3}" ${required} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${esc(Array.isArray(value)?value.join('\n'):value)}</textarea>`:`<input id="${id}" name="${name}" type="${opts.type||'text'}" value="${esc(value)}"${required}${opts.placeholder?` placeholder="${esc(opts.placeholder)}"`:''}${opts.pattern?` pattern="${esc(opts.pattern)}"`:''}${opts.maxlength?` maxlength="${opts.maxlength}"`:''}>`;return `<div class="form-field${cls}"><label for="${id}">${esc(label)}${opts.required?' <span class="required">*</span>':''}</label>${control}${opts.help?`<small>${esc(opts.help)}</small>`:''}</div>`}
function formModal(type,title,subtitle,fields,id=''){showModal(title,subtitle,`<form id="record-form" data-type="${type}" data-id="${esc(id)}"><div class="modal-body"><div class="modal-form-error" role="alert"></div><div class="form-grid">${fields}</div></div><div class="modal-footer"><button class="button ghost" type="button" data-action="close-modal">Cancelar</button><button class="button primary" type="submit">${icon('save')}Salvar registro</button></div></form>`)}
function issueForm(issue={}){formModal('issue',issue.id?`Editar #${issue.id}`:'Adicionar issue ou PR','Qualquer issue pode ser acompanhada. A prioridade inicial segue a ordem recomendada.',`${field('id','Número no GitHub',issue.id||'',{required:true,type:'number',help:'Use o número da issue ou do pull request.'})}${field('kind','Tipo',issue.kind||'issue',{options:[['issue','Issue'],['pr','Pull request']]})}${field('title','Título',issue.title||'',{full:true,required:true})}${field('summary','Impacto e contexto',issue.summary||'',{full:true,textarea:true})}${field('priority','Prioridade',issue.priority||'P2',{options:[['P0','P0 · Urgente'],['P1','P1 · Alta'],['P2','P2 · Média'],['P3','P3 · Baixa']]})}${field('risk','Risco',issue.risk||(issue.id?'unknown':'medium'),{options:Object.entries(riskLabels)})}${field('status','Estado no GitHub',issue.github_state||issue.status||'open',{options:[['open','Aberta'],['closed','Fechada'],['merged','PR integrado']]})}${field('fix_status','Estado da correção',issue.fix_status||'needs_validation',{options:[['needs_validation','Validar localmente'],['pending','Pendente'],['in_progress','Em andamento'],['fixed','Correção implementada'],['verified','Correção verificada']]})}${field('url','URL da fonte',issue.url||'',{type:'url',full:true,placeholder:'https://github.com/Mudlet/Mudlet/issues/…'})}`,issue.id)}
function runForm(run={}){formModal('run',run.id?'Editar execução':'Registrar execução',run.id?'Editar a evidência remove a marca de verificação anterior. Revise novamente após salvar.':'Registre somente o que foi executado. Mock não conta como integração live.',`<div class="form-section-title">01 · Contexto do código</div><div class="form-field"><label for="field-issue_id">Número da issue / PR <span class="required">*</span></label><input id="field-issue_id" name="issue_id" type="number" min="1" required list="issues-suggest" value="${esc(run.issue_id||'')}" placeholder="Ex.: 12189"><datalist id="issues-suggest">${issueSorted().slice(0,100).map(i=>`<option value="${esc(i.id)}">${esc(i.title)}</option>`).join('')}</datalist><small>Digite qualquer número. Sugestões limitadas aos primeiros 100 itens.</small></div>${field('status','Resultado',run.status||'pending',{options:[['pending','Pendente'],['passed','Aprovado'],['failed','Falhou'],['blocked','Bloqueado']]})}${field('commit_sha','SHA completo do commit',run.commit_sha||'',{required:true,pattern:'(?:[a-fA-F0-9]{40}|[a-fA-F0-9]{64})',placeholder:'Hash Git do código efetivamente testado',help:'Prefira o SHA completo, sem nome de branch.'})}${field('method_hash','Hash do método-fonte',run.method_hash||'',{placeholder:'SHA-256 do trecho de código',pattern:'(?:[a-fA-F0-9]{40}|[a-fA-F0-9]{64})',help:'Calcule no arquivo/intervalo exato e registre o algoritmo.'})}${field('source_method','Métodos e localização da fonte',run.source_method||run.source_methods||'',{full:true,textarea:true,placeholder:'Arquivo · classe::método · linhas · algoritmo do hash'})}<div class="form-section-title">02 · Ambiente e protocolo</div>${field('os','Sistema operacional',run.os||'',{required:true,placeholder:'Linux / macOS / Windows + versão'})}${field('mode','Modo',run.mode||'mock',{options:[['mock','Mock · sem Mudlet real'],['live','Live · Mudlet em execução']]})}${field('endpoint','Endpoint loopback',run.endpoint||state.meta.protocol?.loopback||'http://127.0.0.1:11235/mcp',{placeholder:'http://127.0.0.1:porta/mcp',help:'Registre o endpoint usado; ele não será acessado pelo navegador.'})}${field('protocol_version','Versão negociada do MCP',run.protocol_version||'',{placeholder:'Versão efetivamente retornada pelo servidor'})}${field('tools','Ferramentas testadas',run.tools||[],{textarea:true,placeholder:'Uma ferramenta por linha',help:'Use os nomes exatos expostos por tools/list.'})}${field('safe_lua','Comandos Lua inofensivos',run.safe_lua||[],{textarea:true,placeholder:'Ex.: return 1 + 1',help:'Registro de evidência. Este formulário não executa Lua.'})}<div class="form-section-title">03 · Cobertura e resultados</div>${field('scope','Escopo executado',run.scope||'isolated',{options:Object.entries(scopeLabels)})}${field('risk','Risco',run.risk||'medium',{options:Object.entries(riskLabels)})}${field('priority','Prioridade',run.priority||'P2',{options:[['P0','P0 · Urgente'],['P1','P1 · Alta'],['P2','P2 · Média'],['P3','P3 · Baixa']]})}${field('fix_status','Estado da correção',run.fix_status||'needs_validation',{options:[['needs_validation','Validar localmente'],['pending','Pendente'],['in_progress','Em andamento'],['fixed','Implementada'],['verified','Verificada']]})}${field('assertions_passed','Asserções aprovadas',run.assertions_passed||[],{textarea:true,placeholder:'Uma asserção observada por linha'})}${field('assertions_failed','Asserções falhadas',run.assertions_failed||[],{textarea:true,placeholder:'Uma falha observada por linha'})}${field('reproduction','Entradas e passos de reprodução',run.reproduction||'',{full:true,textarea:true,rows:4,help:'Inclua entrada exata, esperado, observado e sequência de comandos.'})}${field('e2e_coverage','Cobertura de ponta a ponta e lacunas',run.e2e_coverage||'',{full:true,textarea:true,help:'Informe o caminho real percorrido e o que ainda não foi exercitado.'})}${field('build_url','URL do build / artefato',run.build_url||'',{full:true,type:'url',placeholder:'https://github.com/Mudlet/Mudlet/actions/runs/…'})}`,run.id)}
function integrationForm(id){const t=state.integration_tests.find(t=>String(t.id)===String(id));if(!t)return;formModal('integration',t.title,'Aprovação exige evidência. Vincule a execução, o commit e o ambiente nas observações.',`${field('status','Resultado do cenário',t.status||'pending',{full:true,options:[['pending','Pendente'],['passed','Aprovado'],['failed','Falhou'],['blocked','Bloqueado']]})}${field('run_ids','IDs das execuções vinculadas',t.run_ids||[],{full:true,textarea:true,rows:2,help:'Um ID por linha. Aprovação exige execução live aprovada, verificada, com evidência completa e da mesma issue.'})}${field('notes','Evidência e próximos passos',t.notes||'',{full:true,textarea:true,rows:6,required:true,placeholder:'ID da execução · SHA · ambiente · observado · lacunas'})}`,t.id)}
function availabilityForm(entry={}){formModal('availability',entry.id?'Editar evidência':'Registrar evidência de disponibilidade','Confirme uma categoria por vez. Sem fonte primária verificável, mantenha “Não confirmado”.',`${field('category','Categoria',entry.category||'native',{options:Object.entries(categoryLabels)})}${field('status','Estado da evidência',entry.status||'unconfirmed',{options:[['unconfirmed','Não confirmado'],['documented','Documentado · sem instalação validada'],['confirmed','Confirmado'],['unavailable','Indisponível']]})}${field('name','Artefato / capacidade',entry.name||entry.title||'',{required:true,full:true,placeholder:'Nome da integração, versão ou capacidade observada'})}${field('source_url','URL da fonte primária',entry.source_url||'',{full:true,type:'url',help:'Release oficial, documentação original ou repositório do autor.'})}${field('checked_at','Data da checagem',entry.checked_at?String(entry.checked_at).slice(0,10):new Date().toISOString().slice(0,10),{type:'date'})}${field('version','Versão / release',entry.version||'')}${field('evidence_type','Tipo de fonte',entry.evidence_type||'primary',{options:[['primary','Primária · autor, release ou documentação oficial'],['secondary','Secundária · relato / menção']]})}${field('install_url','URL do artefato / instalação',entry.install_url||'',{type:'url',help:'Obrigatória ao confirmar plugin, conector, pacote ou repositório.'})}${field('notes','O que foi confirmado e o que falta',entry.notes||'',{full:true,required:true,textarea:true,rows:5,help:'Instalação, transporte MCP, compatibilidade ChatGPT, artefato e teste reproduzível.'})}`,entry.id)}
function issueDetail(id){const issue=getIssue(id);if(!issue){toast('Importe ou cadastre esta issue para abrir o contexto.',true);return}const runs=runsFor(id);const gh=issue.github||{};const combine=(a,b)=>[...list(a),...list(Array.isArray(b)?b:b?.items)];const collections=[['Commits',combine(issue.commits,gh.commits)],['Pull requests relacionados',combine(issue.prs||issue.pull_requests||issue.related_prs,gh.pull_request?[gh.pull_request]:[])],['Sandbox publicado (evidência externa)',issue.sandbox_results||[]],['Comentários',combine(issue.comments,gh.comments)],['Revisões',combine(issue.reviews,gh.reviews)],['Comentários de revisão',gh.review_comments?.items||[]],['Checks e builds de teste',combine(issue.builds||issue.check_runs,gh.checks)],['Workflows',gh.builds?.items||[]],['Eventos do GitHub',gh.events?.items||[]]];showModal(`#${issue.id} · ${issue.title}`,`${issue.kind==='pr'?'Pull request':'Issue'} · GitHub e validação local registrados separadamente`, `<div class="modal-body"><div class="detail-header">${priority(issue.priority)}${badge(issue.github_state||issue.status)}${riskBadge(issue.risk)}${localValidation(issue)}</div><p class="detail-description">${esc(issue.summary||issue.description||issue.body||'Consulte a fonte primária para o contexto completo.')}</p><div class="detail-grid"><div class="detail-value"><span>Estado da correção</span><p>${esc(statusLabels[issue.fix_status]||issue.fix_status||'A validar')}</p></div><div class="detail-value"><span>Fonte / atualização</span><p>${link(issue.url||`https://github.com/Mudlet/Mudlet/issues/${issue.id}`,'Abrir no GitHub')}<br><span class="cell-sub">${esc(date(issue.updated_at||issue.source_checked_at,true))}</span></p></div></div>${issue.reproduction?`<div class="detail-section"><h3>Reprodução</h3><pre>${esc(issue.reproduction)}</pre></div>`:''}${sourceMethodsDetail(issue.source_methods)}${gh.build_scope?`<div class="detail-alert">Cobertura de importação de builds: ${esc(typeof gh.build_scope==='string'?gh.build_scope:JSON.stringify(gh.build_scope))}. CI upstream não equivale a teste local.</div>`:''}${collections.map(([title,items])=>`<div class="detail-section"><h3>${esc(title)} <span class="counter">${list(items).length}</span></h3>${list(items).length?list(items).map(item=>{if(typeof item==='string')return `<div class="evidence-line"><span>${esc(item)}</span></div>`;const label=item.title||item.summary||item.message||item.name||item.excerpt||item.body||item.event||item.sha||item.number||item.id||'Registro';return `<div class="evidence-line"><span>${item.html_url||item.url?link(item.html_url||item.url,String(label).slice(0,300)):esc(String(label).slice(0,300))}</span><span class="muted">${esc([item.author||item.actor, item.sha||item.commit_sha ? shorten(item.sha||item.commit_sha,12) : '', item.state||item.conclusion||item.status, item.created_at||item.date ? date(item.created_at||item.date) : ''].filter(Boolean).join(' · '))}</span></div>`}).join(''):'<p class="small muted">Sem registros importados. Use a sincronização detalhada do GitHub para esta issue.</p>'}</div>`).join('')}<div class="detail-section"><h3>Execuções locais <span class="counter">${runs.length}</span></h3>${runs.length?runs.map(r=>`<div class="evidence-line"><button class="text-btn" data-action="run-detail" data-id="${esc(r.id)}">${esc(shorten(r.commit_sha))} · ${esc(scopeLabels[r.scope]||r.scope)} · ${esc(r.mode)}</button>${badge(r.status)}</div>`).join(''):'<p class="small muted">Nenhuma execução registrada para este código.</p>'}</div><div class="detail-alert">O estado “fechada” ou “integrado” no GitHub não comprova execução local de GUI, parser, suite completa ou E2E.</div><div class="detail-section" id="generated-note"></div></div>`,`<div class="modal-footer"><button class="button ghost" data-action="edit-issue" data-id="${esc(id)}">${icon('edit')}Editar</button><button class="button" data-action="generate-note" data-id="${esc(id)}">${icon('note')}Gerar nota curta</button><button class="button primary" data-action="new-run" data-issue="${esc(id)}">${icon('plus')}Registrar teste</button></div>`)}
function runDetail(id){const r=state.runs.find(r=>String(r.id)===String(id));if(!r)return;const kv=[['Commit',r.commit_sha],['Hash do método-fonte',r.method_hash||JSON.stringify(r.method_hashes||[])],['Sistema operacional',r.os],['Modo / escopo',`${r.mode} · ${scopeLabels[r.scope]||r.scope}`],['Endpoint loopback',r.endpoint],['Protocolo MCP',r.protocol_version],['Risco / prioridade',`${riskLabels[r.risk]||r.risk||'—'} · ${r.priority||'—'}`],['Correção',statusLabels[r.fix_status]||r.fix_status||'A validar']];showModal(`Execução · #${r.issue_id}`,`${r.id} · ${date(r.created_at,true)}`,`<div class="modal-body"><div class="detail-header">${badge(r.status)}${pill(r.mode,r.mode==='live'?'blue':'neutral')}${r.verified?pill(`Verificado por ${r.reviewer}`,'green','checkcircle'):pill('Ainda não revisado','yellow')}</div><div class="detail-grid">${kv.map(([label,value])=>`<div class="detail-value"><span>${esc(label)}</span><p class="${label.includes('Hash')||label==='Commit'?'mono':''}">${esc(value||'Não informado')}</p></div>`).join('')}</div>${r.source_method||r.source_methods?`<div class="detail-section"><h3>Métodos-fonte</h3><pre>${esc(r.source_method||r.source_methods)}</pre></div>`:''}${[['Ferramentas testadas',r.tools],['Lua inofensivo',r.safe_lua],['Asserções aprovadas',r.assertions_passed],['Asserções falhadas',r.assertions_failed]].map(([title,values])=>`<div class="detail-section"><h3>${esc(title)} <span class="counter">${list(values).length}</span></h3>${list(values).length?`<pre>${esc(list(values).join('\n'))}</pre>`:'<p class="small muted">Nenhuma registrada.</p>'}</div>`).join('')}<div class="detail-section"><h3>Reprodução</h3><pre>${esc(r.reproduction||'Não registrada.')}</pre></div><div class="detail-section"><h3>Cobertura de ponta a ponta</h3><p class="detail-description">${esc(r.e2e_coverage||'Cobertura não documentada. Não presumir validação de ponta a ponta.')}</p></div>${r.build_url?`<div class="detail-section">${link(r.build_url,'Build / artefato de teste')}</div>`:''}${r.verified?`<div class="detail-alert">Revisado por ${esc(r.reviewer)} em ${esc(date(r.verified_at,true))}. A verificação humana não amplia o escopo executado.</div>`:''}</div>`,`<div class="modal-footer"><button class="button" data-action="edit-run" data-id="${esc(id)}">${icon('edit')}Editar</button><button class="button primary" data-action="verify-run" data-id="${esc(id)}">${icon('shield')}${r.verified?'Revisar marcação':'Marcar verificado'}</button></div>`)}
function verifyForm(id){const r=state.runs.find(x=>String(x.id)===String(id));if(!r)return;formModal('verify',r.verified?'Revisão do resultado':'Marcar resultado como verificado','A marca registra uma revisão humana da evidência e do escopo executado.',`${field('reviewer','Nome do revisor',r.reviewer||'',{required:true,full:true})}${field('verified','Marcação',r.verified?'false':'true',{full:true,options:[['true','Verificado · revisei a evidência'],['false','Não verificado · remover marcação']]})}<div class="full notice">${icon('info')}<div>Marcar como verificado preserva o resultado e o escopo. Um teste mock continua sendo mock; um teste isolado continua sendo isolado.</div></div>`,id)}
async function renderLogin(error=''){let session={};try{session=await api('auth/session');state.csrf=session.csrf||state.csrf}catch{}app.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-brand"><div class="brand-mark">m<span>_</span></div><div><div class="brand-name">Mudlet</div><div class="brand-sub">Control Room</div></div></div><div class="eyebrow">Acesso ao workspace</div><h1 class="section-gap">Todas as evidências.<br>Um lugar.</h1><p>Entre para acompanhar o desenvolvimento e validar a integração Mudlet–ChatGPT.</p>${!session.configured&&!session.dev_local?`<div class="notice"><div>Configure <code>APP_PASSWORD</code> no servidor. Para desenvolvimento apenas em loopback, use <code>APP_DEV_LOCAL=1</code>.</div></div>`:`<form id="login-form"><div class="modal-form-error" role="alert"></div>${field('password','Senha do workspace','',{required:true,type:'password'})}<button class="button primary" type="submit">Entrar no Control Room ${icon('arrow')}</button></form>`}<p class="login-note">Sessão protegida · Dados persistentes no servidor</p></div></div>`}
function sourceMethodsDetail(methods){return !list(methods).length?'':`<div class="detail-section"><h3>Métodos-fonte e hashes <span class="counter">${list(methods).length}</span></h3>${list(methods).map(m=>typeof m==='string'?`<pre>${esc(m)}</pre>`:`<div class="source-method"><h4>${esc(m.symbol||m.method||m.name||'Método')}</h4><p>${link(m.source_url||m.url,`${m.path||m.file||'Fonte'}:${m.start_line||'?'}–${m.end_line||'?'}`)}</p><div class="detail-value"><span>Commit da fonte</span><p class="mono">${esc(m.commit_sha||m.commit||'Não informado')}</p></div><div class="detail-value"><span>${esc(m.algorithm||'SHA-256')} · hash do método</span><p class="mono">${esc(m.hash||m.method_sha256||'Não informado')}</p></div><p class="small muted">${esc(m.hash_scope||m.hash_algorithm||'Escopo do hash não documentado.')}</p><p class="small muted">${m.hash_verified_here?'Hash conferido neste workspace. ':''}${m.runtime_tested_here?'Execução local documentada.':'Hash conferido não implica teste de runtime.'}</p></div>`).join('')}</div>`}
function updateFiltered(){const el=$('#filtered-content');if(el)el.innerHTML=state.view==='runs'?runsTable(filterRuns()):issuesTable(filterIssues());updateLocation()}
async function handleAction(button){const action=button.dataset.action,id=button.dataset.id;try{switch(action){case 'page-prev':state.page=Math.max(1,state.page-1);updateFiltered();break;case 'page-next':state.page++;updateFiltered();break;case 'menu':$('#sidebar')?.classList.toggle('open');break;case 'reload':await load();toast('Dados locais atualizados.');break;case 'logout':await api('logout',{});await renderLogin();break;case 'close-modal':closeModal();break;case 'new-issue':issueForm();break;case 'edit-issue':issueForm(getIssue(id)||{});break;case 'issue-detail':issueDetail(id);break;case 'new-run':runForm(button.dataset.issue?{issue_id:button.dataset.issue}:{});break;case 'edit-run':runForm(state.runs.find(r=>String(r.id)===String(id))||{});break;case 'run-detail':runDetail(id);break;case 'verify-run':verifyForm(id);break;case 'edit-integration':integrationForm(id);break;case 'new-availability':availabilityForm();break;case 'edit-availability':availabilityForm(state.availability.find(e=>String(e.id)===String(id))||{});break;case 'save-filter':formModal('filter','Salvar filtro','Sua seleção poderá ser reutilizada nas issues e nas execuções.',field('name','Nome do filtro','',{required:true,full:true,placeholder:'Ex.: Risco alto · pendentes'}));break;case 'apply-filter':{const f=state.filters.find(f=>String(f.id)===String(id));if(f){state.page=1;state.filter={q:'',status:'all',risk:'all',scope:'all',verified:'all',...(f.filters||f.filter||{})};if(f.filters?.view&&navItems.some(n=>n[0]===f.filters.view))state.view=f.filters.view;updateLocation();render()}break}case 'remove-filter':await mutate('filters.remove',{id},'Filtro removido.');break;case 'clear-filters':state.page=1;state.filter={q:'',status:'all',risk:'all',scope:'all',verified:'all'};updateLocation();render();break;case 'sanitizer':state.filter={q:'sanitiz',status:'all',risk:'all',scope:'all',verified:'all'};navigate('issues');break;case 'generate-note':{button.disabled=true;const n=await api('note.generate',{issue_id:Number(id)});const target=$('#generated-note');if(target)target.innerHTML=`<h3>Nota curta · impacto, reprodução e ação</h3><pre class="generated-note">${esc(n.text||`Impacto: ${n.impact||''}\nReprodução: ${n.reproduction||''}\nAção: ${n.action||''}`)}</pre><button class="button small" data-action="copy-note">${icon('copy')}Copiar nota</button>`;break}case 'copy-note':{const text=$('.generated-note')?.textContent||'';if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('Nota copiada.')}else{toast('Selecione o texto da nota para copiar.')}break}}}catch(e){toast(e.message,true)}finally{button.disabled=false}}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){navigate(view.dataset.view);return}const category=e.target.closest('[data-category]');if(category){state.category=category.dataset.category;render();return}const button=e.target.closest('[data-action]');if(button)handleAction(button)});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.filter.q=e.target.value;state.page=1;updateFiltered()}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){state.filter[e.target.dataset.filter]=e.target.value;state.page=1;updateFiltered()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['record-form','compare-form','login-form'].includes(form.id))return;e.preventDefault();const submit=$('button[type="submit"]',form);const error=$('.modal-form-error',form);if(error)error.textContent='';submit.disabled=true;try{const values=Object.fromEntries(new FormData(form));if(form.id==='login-form'){const result=await api('login',{password:values.password});state.csrf=result.csrf||state.csrf;await load();return}if(form.id==='compare-form'){state.compare=await api('compare',values);render();return}const id=form.dataset.id;switch(form.dataset.type){case 'issue':values.id=Number(values.id);values.github_state=values.status;await mutate('issue.save',{issue:values},'Issue salva.');break;case 'run':values.issue_id=Number(values.issue_id);for(const key of ['tools','safe_lua','assertions_passed','assertions_failed'])values[key]=list(values[key]);if(id){values.id=id;const previous=state.runs.find(r=>String(r.id)===String(id));if(previous?.method_hashes)values.method_hashes=previous.method_hashes;}if(values.build_url)values.artifacts=[{url:values.build_url,title:'Build / artefato'}];await mutate('run.save',{run:values},'Execução registrada.');break;case 'verify':await mutate('run.verify',{id,verified:values.verified==='true',reviewer:values.reviewer},'Revisão atualizada.');break;case 'integration':await mutate('integration.update',{id,status:values.status,notes:values.notes,run_ids:list(values.run_ids)},'Evidência da integração atualizada.');break;case 'availability':if(id)values.id=id;if(values.checked_at)values.checked_at=new Date(`${values.checked_at}T12:00:00Z`).toISOString();await mutate('availability.save',{entry:values},'Disponibilidade atualizada.');break;case 'filter':await mutate('filters.save',{name:values.name,filters:{...state.filter,view:state.view}},'Filtro salvo.');break}closeModal()}catch(err){if(error)error.textContent=err.message;else toast(err.message,true)}finally{submit.disabled=false}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('popstate',()=>{readLocation();render()});
readLocation();load();
